create or replace function public.next_estate_subscription_number(_estate_key text,_estate_name text,_estate_code text) returns text language plpgsql security definer set search_path=public as $$ declare n bigint; code text; existing_key text; begin select estate_key,next_number,estate_code into existing_key,n,code from public.estate_subscription_counters where estate_key=_estate_key or estate_code=_estate_code order by (estate_key=_estate_key) desc limit 1 for update; if existing_key is null then insert into public.estate_subscription_counters(estate_key,estate_code) values (_estate_key,_estate_code) returning estate_key,next_number,estate_code into existing_key,n,code; end if; update public.estate_subscription_counters set next_number=n+1,updated_at=now() where estate_key=existing_key; return code||'/'||lpad(n::text,3,'0'); end; $$;
